#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<string> grid(N);
    for (int i = 0; i < N; ++i) {
        cin >> grid[i];
    }

    if (grid[0][0] - '0' <= F) {
        queue<pair<int, int>> q;
        grid[0][0] = '*';
        q.push({0, 0});

        int dr[4] = {-1, 1, 0, 0};
        int dc[4] = {0, 0, -1, 1};

        while (!q.empty()) {
            auto [r, c] = q.front();
            q.pop();

            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k];
                int nc = c + dc[k];

                if (nr < 0 || nr >= N || nc < 0 || nc >= N) continue;
                if (grid[nr][nc] != '*' && grid[nr][nc] - '0' <= F) {
                    grid[nr][nc] = '*';
                    q.push({nr, nc});
                }
            }
        }
    }

    for (const string &row : grid) {
        cout << row << '\n';
    }

    return 0;
}
